examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchTextField(
        value = value,
        onValueChange = { value = it },
        modifier = Modifier.fillMaxWidth(),
        label = {{label}},
        helperText = {{hint}},
        singleLine = false,
    )
    MonarchMentionPicker(
        query = query,
        items = people,
        onSelect = { item ->
            if (query != null) value = query.replacing(value, item.token() + " ")
        },
    )
}

examples.setupTemplate:
var value by remember { mutableStateOf(TextFieldValue({{text}}, TextRange({{text}}.length))) }
val people = listOf(
    MonarchMentionItem(id = {{suggestions.0.id}}, label = {{suggestions.0.label}}, detail = {{suggestions.0.description}}),
)
val query = MonarchMentionQuery.find(value)

